RespPage RespPage::fromJson(const json &j) 

Source code:
RespPage RespPage::fromJson(const json &j) {
  RespPage respPage;
  respPage.size = j.value("size", 0);
  respPage.totalElements = j.value("totalElements", int64_t{0});
  respPage.totalPages = j.value("totalPages", 0);
  respPage.number = j.value("number", 0);
  return respPage;
}
